{
  "title": "Đà Lạt gần gũi, nhẹ tênh",
  "summary": "Một ngày quanh hồ và phố trung tâm, đi bộ thong thả, ăn ngon và kết thúc bằng cà phê đêm.",
  "stops": [
    {
      "poi_id": "p131",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bắt đầu muộn nên ra hồ cho thoáng, ngắm nước và hít không khí núi."
    },
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Ăn trưa ngay gần hồ, món bánh căn nóng hổi vừa túi tiền."
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa gần đó, đi chậm rãi ngắm màu sắc, không cần xe cộ gì."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi xuống ăn nem nướng đúng kiểu ngồi bàn, ấm bụng."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Cà phê đêm cho cú đêm, ngồi một chỗ nghe phố núi về khuya."
    }
  ]
}
```

